/* Event timing chains: natal node representatives and ranked query-time LSRD. */
(function(root){'use strict';
const IDS=['Su','Mo','Ma','Me','Ju','Ve','Sa','Ra','Ke'],SIGN_LORDS=['Ma','Ve','Me','Mo','Su','Me','Ve','Ma','Ju','Sa','Sa','Ju'],ORDER=['Ke','Ve','Su','Mo','Ma','Ra','Ju','Sa','Me'],YEARS={Ke:7,Ve:20,Su:6,Mo:10,Ma:7,Ra:18,Ju:16,Sa:19,Me:17},SIGN=108000,STAR=48000;
const SIGNS=['Aries','Taurus','Gemini','Cancer','Leo','Virgo','Libra','Scorpio','Sagittarius','Capricorn','Aquarius','Pisces'],NAKS=['Ashwini','Bharani','Krittika','Rohini','Mrigashira','Ardra','Punarvasu','Pushya','Ashlesha','Magha','Purva Phalguni','Uttara Phalguni','Hasta','Chitra','Swati','Vishakha','Anuradha','Jyeshtha','Mula','Purva Ashadha','Uttara Ashadha','Shravana','Dhanishtha','Shatabhisha','Purva Bhadrapada','Uttara Bhadrapada','Revati'];
function representative(id,model){if(!['Ra','Ke'].includes(id))return id;const p=model?.planets?.find(p=>p.id===id),sign=Number.isInteger(p?.signIndex)?p.signIndex:Number.isInteger(p?.sign)?p.sign:Number.isFinite(p?.totalArcSeconds)?Math.floor(p.totalArcSeconds/SIGN):null;if(sign===null||sign<0||sign>11)throw Error('Natal Rashi is required for '+id+' sign representation.');return SIGN_LORDS[sign];}
function signs(id,model,represent=true){if(['Ra','Ke'].includes(id)&&!represent)return [];const owner=representative(id,model);return SIGN_LORDS.flatMap((p,i)=>p===owner?[i]:[]);}
function sectors(signList,starLord,subLord=null){const rows=[];for(const sign of signList)for(let nak=0;nak<27;nak++){if(starLord&&ORDER[nak%9]!==starLord)continue;const lower=Math.max(sign*SIGN,nak*STAR),upper=Math.min((sign+1)*SIGN,(nak+1)*STAR);if(lower>=upper)continue;if(!subLord){rows.push({sign,nak,starLord:ORDER[nak%9],lower,upper});continue;}let start=nak*STAR;for(let i=0;i<9;i++){const sub=ORDER[(nak%9+i)%9],end=start+STAR*YEARS[sub]/120;if(sub===subLord&&Math.max(lower,start)<Math.min(upper,end))rows.push({sign,nak,starLord:ORDER[nak%9],subLord:sub,lower:Math.max(lower,start),upper:Math.min(upper,end)});start=end;}}return rows;}
function pair(md,ad,model){
 // A genuine reverse pair takes precedence over inventing an owned sign for a node.
 let rows=sectors(signs(md,model,false),ad);if(rows.length)return {kind:'direct',signRole:'MD',starRole:'AD',signLord:md,starLord:ad,segments:rows};
 rows=sectors(signs(ad,model,false),md);if(rows.length)return {kind:'reverse',signRole:'AD',starRole:'MD',signLord:ad,starLord:md,segments:rows};
 if(['Ra','Ke'].includes(md)){rows=sectors(signs(md,model),ad);if(rows.length)return {kind:'node-direct',signRole:'MD',starRole:'AD',signLord:md,representative:representative(md,model),starLord:ad,segments:rows};}
 if(['Ra','Ke'].includes(ad)){rows=sectors(signs(ad,model),md);if(rows.length)return {kind:'node-reverse',signRole:'AD',starRole:'MD',signLord:ad,representative:representative(ad,model),starLord:md,segments:rows};}
 return null;
}
function lsrd(rp){if(!rp?.ready)return [];const candidates=[['L',rp.points?.find(p=>p.id==='As')?.sgl],['S',rp.points?.find(p=>p.id==='Mo')?.stl],['R',rp.points?.find(p=>p.id==='Mo')?.sgl],['D',rp.dayLord]],seen=new Set(),excluded=new Set(rp.excludedRulers||[]);return candidates.flatMap(([rank,id])=>{if(!IDS.includes(id)||seen.has(id)||excluded.has(id))return [];seen.add(id);return [{rank,id}];});}
function chain(md,ad,model,rp,rulingModel=model){const direct=pair(md,ad,model);if(direct)return direct;const rulers=lsrd(rp);for(const [role,id] of [['MD',md],['AD',ad]])for(const ruler of rulers){const rows=sectors(signs(ruler.id,rulingModel),id);if(rows.length)return {kind:'lsrd-star',rank:ruler.rank,ruler:ruler.id,signLord:ruler.id,representative:representative(ruler.id,rulingModel),starRole:role,starLord:id,segments:rows,queryUTC:rp.utc};}
 // Initial workflow also permits a sub-period fallback, after BOTH star searches fail.
 for(const [role,id] of [['MD',md],['AD',ad]])for(const ruler of rulers){const rows=sectors(signs(ruler.id,rulingModel),null,id);if(rows.length)return {kind:'lsrd-sub',rank:ruler.rank,ruler:ruler.id,signLord:ruler.id,representative:representative(ruler.id,rulingModel),subRole:role,subLord:id,segments:rows,queryUTC:rp.utc};}return {kind:'unavailable',segments:[],reason:'No eligible LSRD ruler can complete this chain.'};}
function degree(arc){const v=Math.round(arc),d=Math.floor(v/3600),m=Math.floor(v%3600/60),s=v%60;return d+'°'+String(m).padStart(2,'0')+'′'+String(s).padStart(2,'0')+'″';}
function describe(c,s){const method=c.kind.startsWith('lsrd')?'LSRD '+c.rank+' '+c.ruler+' → '+(c.starRole||c.subRole)+' '+(c.starLord||c.subLord):c.signRole+' '+c.signLord+(c.representative?' ('+c.representative+' representative)':'')+' → '+c.starRole+' '+c.starLord;return method+' · '+SIGNS[s.sign]+' / '+NAKS[s.nak]+(s.subLord?' / sub '+s.subLord:'')+' · '+degree(s.lower-s.sign*SIGN)+'–'+degree(s.upper-s.sign*SIGN);}
function sunTracks(lords,model,rp,rulingModel){const c=chain(lords.MD,lords.AD,model,rp,rulingModel);return {chain:c,tracks:c.segments.map((s,i)=>({id:'sun:'+c.kind+':'+s.sign+':'+s.nak+':'+i,planet:'Su',label:describe(c,s),levels:s.subLord?['sign','star','sub']:['sign','star'],chain:c,sector:s,test:p=>p.signIndex===s.sign&&p.nakIndex===s.nak&&(!s.subLord||p.sl===s.subLord)}))};}
function mutualTracks(lords,model,{zone='lord',direction='all',level='all'}={}){const tracks=[];for(const moving of ['MD','AD','PD'])for(const target of ['MD','AD','PD'])if(moving!==target&&(direction==='all'||direction===moving+'>'+target))for(const field of ['sign','star','sub'].filter(f=>level==='all'||f===level)){const id=lords[target],point=model?.planets?.find(p=>p.id===id),owned=signs(id,model);if(zone==='natal'&&!point)throw Error('Natal planet is unavailable: '+id);const test=zone==='natal'?p=>field==='sign'?p.signIndex===point.signIndex:field==='star'?p.nakIndex===point.nakIndex:p.nakIndex===point.nakIndex&&p.sl===point.sl:field==='sign'?p=>owned.includes(p.signIndex):field==='star'?p=>p.stl===id:p=>p.sl===id;tracks.push({id:moving+'>'+target+':'+field,planet:lords[moving],label:moving+' '+lords[moving]+' through '+target+' '+id+' '+field+(field==='sign'&&['Ra','Ke'].includes(id)?' ('+representative(id,model)+' representative)':'')+' · '+zone,levels:[field],test});}return tracks;}
function unpaired(model){const out=[];for(let i=0;i<IDS.length;i++)for(let j=i+1;j<IDS.length;j++)if(!pair(IDS[i],IDS[j],model))out.push([IDS[i],IDS[j]]);return out;}
function searchRange(range,data,{source='date',now=Date.now()}={}){let lower=+range.start,upper=+range.end;if((source==='auto-forward'||source==='current')&&upper>now)lower=Math.max(now,lower);if(source==='selected'){lower=Math.max(lower,Date.parse(data.periods.PD.startUTC));upper=Math.min(upper,Date.parse(data.periods.PD.endUTC));}if(!Number.isFinite(lower)||!Number.isFinite(upper)||upper<=lower)throw Error('The dates do not overlap the selected PD. Choose DBA at start date, another PD, or adjust the dates.');return {start:new Date(lower),end:new Date(upper)};}
function eligiblePeriods(periods,significators){const selected=new Set(significators);return periods.filter(p=>p.lords?.length===3&&p.lords.every(l=>selected.has(l.id)));}
async function search({mode,periods,significators,model,rp,rulingModel,eventTracks=[],mutual={},scan,shouldCancel=()=>false,onProgress=()=>{}}){const eligible=eligiblePeriods(periods,significators),results=[],evidence=[];let index=0;for(const p of eligible){if(shouldCancel())throw Error('Search cancelled.');const lords=Object.fromEntries(p.lords.map(l=>[l.level,l.id])),made=mode==='sun'?sunTracks(lords,model,rp,rulingModel):null,tracks=mode==='event'?eventTracks:mode==='sun'?made.tracks:mutualTracks(lords,model,mutual);if(made)evidence.push({start:p.start,end:p.end,lords,chain:made.chain});if(!tracks.length){index++;continue;}const found=await scan({start:new Date(p.start),end:new Date(p.end),tracks,shouldCancel,onProgress:f=>onProgress((index+f)/Math.max(1,eligible.length))});if(shouldCancel())throw Error('Search cancelled.');for(const hit of found){const a=Math.max(Date.parse(hit.start),Date.parse(p.start)),b=Math.min(Date.parse(hit.end),Date.parse(p.end));if(b>a)results.push({...hit,start:new Date(a).toISOString(),end:new Date(b).toISOString(),lords:p.lords,DBA:lords,dbaStart:p.start,dbaEnd:p.end,label:hit.label+' · MD '+lords.MD+' / AD '+lords.AD+' / PD '+lords.PD,...(made?{chainKind:made.chain.kind,rulingRank:made.chain.rank||null,rulingQueryUTC:made.chain.queryUTC||null}:{} )});}if(results.length>50000)throw Error('More than 50,000 transit intervals match. Choose a shorter forward horizon.');index++;onProgress(index/Math.max(1,eligible.length));}return {results:results.sort((a,b)=>a.start.localeCompare(b.start)||a.planet.localeCompare(b.planet)),evidence,eligible};}
root.KPTransitEventChains={representative,signs,sectors,pair,lsrd,chain,sunTracks,mutualTracks,unpaired,searchRange,eligiblePeriods,search};
})(globalThis);
